package br.com.sussmartcare.notification.infrastructure; import br.com.sussmartcare.notification.application.NotificationChannel; import br.com.sussmartcare.notification.domain.Notification; import org.slf4j.*; import org.springframework.stereotype.Component; @Component public class PushNotificationChannel implements NotificationChannel {private static final Logger log=LoggerFactory.getLogger(PushNotificationChannel.class);public boolean supports(String c){return "PUSH".equalsIgnoreCase(c);}public void send(Notification n){log.info("notification_delivered_simulated adapter=PUSH patient={} visit={} type={}",n.getPatientId(),n.getVisitId(),n.getType());}}
